#include "stdafx.h"

// =============================================================================
//  LocalizationIT.cpp    The Hell 4 -- Italian overlay
//  LANG_IT = 5. Latin script, PLAIN ASCII: no accents.
//
//  Italian text is written UNACCENTED (ASCII-folded), sharing the Spanish font /
//  codepage fold tables (dataseg.cpp). Ordinary C string literals only: no \xNN
//  escapes, no adjacent-literal splitting, no greedy-hex trap. Apostrophes are
//  plain ASCII '.  No datafile / MPQ is mounted for Italian (not needed).
//
//  ---- STATUS -------------------------------------------------------------
//  UI table fully translated. All other tables hold a placeholder row and their
//  getters therefore report 0 rows -> those categories fall back to English until
//  filled. Keys must byte-exactly match the English source literal (case, trailing
//  spaces, colons, %i/%s/%u specifiers preserved).
//
//  English source and the RU/ID/PT/ES tables are never touched from this file.
// =============================================================================

struct UiStr  { const char* en; const char* it; }; // .it column holds the IT text
struct IdxStr { int index; const char* tr; };

enum {
	OVL_UI = 0, OVL_MENU, OVL_UNIQUE_ITEM, OVL_AFFIX_PREFIX, OVL_AFFIX_SUFFIX,
	OVL_BASE_ITEM, OVL_BASE_NAME2, OVL_ELEMENT, OVL_SPICIES, OVL_ICEAGE,
	OVL_SPELL, OVL_SPELL_NOM, OVL_PERK_NAME, OVL_PERK_DESC, OVL_WARP,
	OVL_STR_COUNT
};
enum { OVL_SPEECH = 0, OVL_ONSCREEN, OVL_QUEST, OVL_IDX_COUNT };

