static bool isPlaceholder( const IdxStr& r ) { return r.index < 0 && r.tr == 0; }

template<typename T, size_t N>
static int countRows( const T (&arr)[N] )
{
	if( N == 1 && isPlaceholder( arr[0] ) ) return 0;
	return (int)N;
}

const UiStr* IT_GetStrTable( int ovlId, int* n )
{
	switch( ovlId ){
		case OVL_UI:           *n = countRows(IT_Ui);          return IT_Ui;
		case OVL_MENU:         *n = countRows(IT_Menu);        return IT_Menu;
		case OVL_UNIQUE_ITEM:  *n = countRows(IT_UniqueItem);  return IT_UniqueItem;
		case OVL_AFFIX_PREFIX: *n = countRows(IT_AffixPrefix); return IT_AffixPrefix;
		case OVL_AFFIX_SUFFIX: *n = countRows(IT_AffixSuffix); return IT_AffixSuffix;
		case OVL_BASE_ITEM:    *n = countRows(IT_BaseItem);    return IT_BaseItem;
		case OVL_BASE_NAME2:   *n = countRows(IT_BaseName2);   return IT_BaseName2;
		case OVL_ELEMENT:      *n = countRows(IT_Element);     return IT_Element;
		case OVL_SPICIES:      *n = countRows(IT_Spicies);     return IT_Spicies;
		case OVL_ICEAGE:       *n = countRows(IT_IceAge);      return IT_IceAge;
		case OVL_SPELL:        *n = countRows(IT_Spell);       return IT_Spell;
		case OVL_SPELL_NOM:    *n = countRows(IT_SpellNom);    return IT_SpellNom;
		case OVL_PERK_NAME:    *n = countRows(IT_PerkName);    return IT_PerkName;
		case OVL_PERK_DESC:    *n = countRows(IT_PerkDesc);    return IT_PerkDesc;
		case OVL_WARP:         *n = countRows(IT_Warp);        return IT_Warp;
	}
	*n = 0; return 0;
}

const IdxStr* IT_GetIdxTable( int ovlId, int* n )
{
	switch( ovlId ){
		case OVL_SPEECH:   *n = countRows(IT_Speech);   return IT_Speech;
		case OVL_ONSCREEN: *n = countRows(IT_OnScreen); return IT_OnScreen;
		case OVL_QUEST:    *n = countRows(IT_Quest);    return IT_Quest;
	}
	*n = 0; return 0;
}

